const AND = (a, b) => a & b;
const OR = (a, b) => a | b;
const NOT = (a) => a ? 0 : 1;

// XOR = (A OR B) AND NOT(A AND B)
function xor(a, b) {
  return AND(OR(a, b), NOT(AND(a, b)));
}

function halfAdder(a, b) {
  return { sum: xor(a, b), carry: AND(a, b) };
}

const r = halfAdder(1, 1);
if (r.sum !== 0 || r.carry !== 1) throw new Error('1+1 should give sum=0 carry=1, got ' + JSON.stringify(r));
console.log('1+1 ->', r);
